    "misconceptions": {
      "DEN_CHANGE": {
        "title": "Changes or subtracts the denominator",
        "observableEvidence": "The denominator becomes zero, changes to d-b, or is described as tracking the number of parts removed.",
        "immediateFeedback": "The whole still has the same equal-part scale.",
        "singleMissPolicy": "One exact equivalent value with another positive denominator is not denominator subtraction. Record form separately and do not over-diagnose.",
        "repairThreshold": "Trigger R-DEN after a repeated denominator change, a failed denominator cue, or an explicit rule to subtract/change the denominator.",
        "repairId": "R-DEN"
      },
      "ADD": {
        "title": "Adds the numerator counts",
        "observableEvidence": "The response uses a+b or the learner explains removal as combining both groups.",
        "immediateFeedback": "This is subtraction. Start with the first count and remove the second.",
        "singleMissPolicy": "A lone wrong subtraction fact is ARITH, not ADD, unless the structure or explanation clearly shows addition.",
        "repairThreshold": "Trigger R-ADD after a repeated add-both response or a clear addition explanation.",
        "repairId": "R-ADD"
      },
      "ORDER": {
        "title": "Reverses start and remove",
        "observableEvidence": "The second numerator is treated as the start, the learner says order does not matter, or intermediate working explicitly uses b-a.",
        "immediateFeedback": "Subtraction follows the start-minus-remove direction.",
        "singleMissPolicy": "A final positive numerical difference alone may not reveal reversed reasoning; use method evidence or a discriminating choice item.",
        "repairThreshold": "Trigger R-ORDER after repeated reversed working, an explicit order-does-not-matter claim, or a failed start/remove cue.",
        "repairId": "R-ORDER"
      },
      "RENAME": {
        "title": "Renames fractions although denominators already match",
        "observableEvidence": "The learner creates a new common denominator or gives an exact equivalent answer when the prompt explicitly requires the original denominator.",
        "immediateFeedback": "The denominators already match; no renaming is needed.",
        "singleMissPolicy": "An exact equivalent value on a value-only item remains mathematically correct. Track form deviation without playing incorrect mathematics feedback.",
        "repairThreshold": "Trigger R-RENAME only after the detour repeats or a form-sensitive instruction is ignored.",
        "repairId": "R-RENAME"
      },
      "VIS": {
        "title": "Miscounts the visual start, removal or remainder",
        "observableEvidence": "The learner double-counts a marked section, counts the removed sections as the remainder, or selects a visually inconsistent model.",
        "immediateFeedback": "Count the start, mark each removed section once, then count what is still selected.",
        "singleMissPolicy": "A visual miscount can resemble COPY or ARITH. Use one fresh discriminating visual before assigning a central repair.",
        "repairThreshold": "Trigger R-VIS after a repeated or structurally clear model-counting error.",
        "repairId": "R-VIS"
      },
      "ARITH": {
        "title": "Subtraction fact slip after correct fraction structure",
        "observableEvidence": "The denominator is retained and the method is subtraction, but the numerator fact is wrong.",
        "immediateFeedback": "The structure is right. Recheck the subtraction fact once.",
        "singleMissPolicy": "Do not route a single fact slip to a denominator, addition or order repair.",
        "repairThreshold": "Use R-ARITH-C as one fresh nearby fact check. Escalate only if later evidence identifies another family.",
        "repairId": "R-ARITH"
      },
      "UNKNOWN": {
        "title": "Blank, malformed or ambiguous response",
        "observableEvidence": "The response contains no usable structure or several explanations remain plausible.",
        "immediateFeedback": "Show me the start and the amount removed.",
        "singleMissPolicy": "Do not pretend to know the learner's misconception from one ambiguous answer.",
        "repairThreshold": "Use R-UNKNOWN-C to collect discriminating evidence before selecting any targeted repair.",
        "repairId": "R-UNKNOWN"
      }
    },
